{"investigation_id": "investigation-5", "question": "renderPage 渲染用户可控页面内容并以 TEXT_HTML 返回，存在存储型 XSS 或模板注入风险。", "entry": "GET /api/pages/{pageId}", "asset": "HTML 响应中的存储型 XSS / 模板注入", "evidence": {"file:00911d3d7aec5c245c62f6e861296151825b31e2527d1e729d508ae1f74b2300:0:1578": {"chunk_id": "file:00911d3d7aec5c245c62f6e861296151825b31e2527d1e729d508ae1f74b2300", "evidence_id": "file:00911d3d7aec5c245c62f6e861296151825b31e2527d1e729d508ae1f74b2300:0:1578", "repository_id": "sinkspring-bench-eval", "snapshot_id": "sinkspring-bench-eval-v1", "source_snapshot_id": "3c2aecab589d4e71a701138c1af6a327", "index_run_id": "a112f871-4f3a-45cf-bd79-dd71986e3c60", "relative_path": "src/main/java/com/sinkspring/bench/controller/PageController.java", "content": "package com.sinkspring.bench.controller;

import com.sinkspring.bench.dto.PageRequest;
import com.sinkspring.bench.service.PageService;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import java.util.Map;

@RestController
@RequestMapping("/api/pages")
public class PageController {

    @Autowired
    private PageService pageService;

    @GetMapping(value = "/search", produces = MediaType.TEXT_HTML_VALUE)
    public String search(@RequestParam String query) {
        return pageService.buildSearchPage(query);
    }

    @PostMapping
    public Map<String, String> save(@RequestBody PageRequest request) {
        pageService.savePage(request);
        return Map.of("pageId", request.getPageId());
    }

    @GetMapping(value = "/{pageId}", produces = MediaType.TEXT_HTML_VALUE)
    public String page(@PathVariable String pageId) {
        return pageService.renderPage(pageId);
    }

    @GetMapping(value = "/search/text", produces = MediaType.TEXT_PLAIN_VALUE)
    public String searchText(@RequestParam String query) {
        return pageService.buildSearchText(query);
    }
}
